//! Source-level transform passes that run on the token stream before the
//! minimal-whitespace render:
//!
//! - PY09 `merge_imports` (default on): joins *adjacent* `import` /
//!   `from m import` statements. Adjacency keeps module-init side-effect
//!   order identical, so this is always behavior-preserving.
//! - PYO2 `strip_docstrings` (opt-in): removes the leading string literal of a
//!   module, class or function body. This *does* empty `__doc__`, breaking
//!   `help()`, doctests and docstring-driven tooling, which is why it is not a
//!   default.
//! - PYO3 `strip_annotations` (opt-in): removes type annotations. This *does*
//!   change `__annotations__` and breaks dataclass/pydantic-style runtime
//!   introspection, which is why it is not a default.
//!
//! Passes return `(tokens, modified)`; when a pass modified the stream, the
//! verifier compares the output against these tokens instead of the original
//! AST (plus an import-preservation check, see `verify`).
use crate::parser::{ast,AstRanged,Module,TextRange,Tok,TokenKind};
/// PY09 - merge adjacent import statements.
///
/// Statements merge only when nothing but blank lines separates them, both
/// are the same flavor (`import` / `from <same module> import`), and neither
/// uses parentheses, `*`, or `;`. Comments and any other statement break the
/// run, so kept comments never move relative to their imports.
pub fn merge_imports<'a>(tokens:&[Tok<'a>])->(Vec<Tok<'a>>,bool){#[derive(PartialEq)]enum Kind{Plain,From(String),}struct Import{kind:Kind,
/// Number of leading tokens forming the `import` / `from m import`
/// prefix that a merged continuation drops.
prefix:usize,}fn scan(tokens:&[Tok<'_>],start:usize)->Option<(Import,usize)>{let mut import_kw=None;let mut end=None;for(offset,tok)in tokens[start..].iter().enumerate(){match tok.kind{TokenKind::Newline=>{end=Some(start+offset);break;}TokenKind::Lpar|TokenKind::Star|TokenKind::Semi|TokenKind::Comment|TokenKind::EndOfFile=>{return None;}TokenKind::Import if offset>0=>import_kw=Some(start+offset),_=>{}}}let end=end?;let import=if tokens[start].kind==TokenKind::Import{Import{kind:Kind::Plain,prefix:1,}}else{let import_kw=import_kw?;let module:String=tokens[start+1..import_kw].iter().filter(|t|t.kind!=TokenKind::NonLogicalNewline).map(|t|t.text).collect();Import{kind:Kind::From(module),prefix:import_kw-start+1,}};Some((import,end))}let mut out:Vec<Tok<'a>> =Vec::new();let mut modified=false;let mut pending:Option<(Kind,Tok<'a>)> =None;let mut at_line_start=true;let mut i=0;while i<tokens.len(){let tok=&tokens[i];if tok.kind==TokenKind::NonLogicalNewline{out.push(tok.clone());at_line_start=true;i+=1;continue;}let import=if at_line_start&&matches!(tok.kind,TokenKind::Import|TokenKind::From){scan(tokens,i)}else{None};match import{Some((stmt,end))=>{match pending.take(){Some((kind,_newline))if kind==stmt.kind=>{modified=true;out.push(Tok{kind:TokenKind::Comma,text:",",range:tok.range,});}Some((_,newline))=>{out.push(newline);out.extend(tokens[i..i+stmt.prefix].iter().cloned());}None=>out.extend(tokens[i..i+stmt.prefix].iter().cloned()),}out.extend(tokens[i+stmt.prefix..end].iter().cloned());pending=Some((stmt.kind,tokens[end].clone()));at_line_start=true;i=end+1;}None=>{if let Some((_,newline))=pending.take(){out.push(newline);}at_line_start=matches!(tok.kind,TokenKind::Newline|TokenKind::Indent|TokenKind::Dedent);out.push(tok.clone());i+=1;}}}if let Some((_,newline))=pending{out.push(newline);}(out,modified)}
/// Spans of docstring statements collected from the AST.
#[derive(Default)]struct DocstringSpans{
/// Docstrings whose body keeps other statements (or is the module body,
/// which may legally end up empty) - deleted.
deletes:Vec<TextRange>,
/// Docstrings that are the only statement of a class/function body -
/// replaced by `pass` so the body stays syntactically valid.
replaced_stmts:Vec<TextRange>,}impl DocstringSpans{
/// Records the docstring of `body`, if it has one. A docstring is a
/// string-literal expression statement in *first* position; a later one is
/// an ordinary expression statement. `needs_pass` is false for the module
/// body, the only body that may legally become empty.
///
/// Implicit concatenation (`"a" "b"`) parses as one string literal and
/// still sets `__doc__`, so it is a docstring; f-strings and byte strings
/// are separate AST nodes that do not set `__doc__`, so they are kept.
fn scan(&mut self,body:&[ast::Stmt],needs_pass:bool){let Some(ast::Stmt::Expr(stmt))=body.first()else{return;};if!matches!(*stmt.value,ast::Expr::StringLiteral(_)){return;}if needs_pass&&body.len()==1{self.replaced_stmts.push(stmt.range());}else{self.deletes.push(stmt.range());}}}impl ast::visitor::Visitor<'_>for DocstringSpans{fn visit_stmt(&mut self,stmt:&ast::Stmt){match stmt{ast::Stmt::FunctionDef(f)=>self.scan(&f.body,true),ast::Stmt::ClassDef(c)=>self.scan(&c.body,true),_=>{}}ast::visitor::walk_stmt(self,stmt);}}
/// PYO2 - strip docstrings, using AST spans to cut tokens.
pub fn strip_docstrings<'a>(tokens:&[Tok<'a>],module:&Module)->(Vec<Tok<'a>>,bool){use ast::visitor::Visitor;let mut spans=DocstringSpans::default();spans.scan(&module.body,false);for stmt in&module.body{spans.visit_stmt(stmt);}let modified=!(spans.deletes.is_empty()&&spans.replaced_stmts.is_empty());if!modified{return(tokens.to_vec(),false);}let inside=|t:&Tok<'_>,s:&TextRange|t.range.start()>=s.start()&&t.range.end()<=s.end();let mut dropped=vec![false;tokens.len()];for span in&spans.deletes{let cut_end=tokens.iter().find(|t|{t.range.start()>=span.end()&&matches!(t.kind,TokenKind::Newline|TokenKind::Semi)}).map_or(span.end(),|t|t.range.end());for(i,tok)in tokens.iter().enumerate(){if tok.range.start()>=span.start()&&tok.range.start()<cut_end&&tok.kind!=TokenKind::Comment{dropped[i]=true;}}}let mut out:Vec<Tok<'a>> =Vec::new();let mut replaced_span:Option<TextRange> =None;for(i,tok)in tokens.iter().enumerate(){let replacement=spans.replaced_stmts.iter().find(|s|inside(tok,s)).copied();if let Some(span)=replacement{if replaced_span!=Some(span){replaced_span=Some(span);out.push(Tok{kind:TokenKind::Pass,text:"pass",range:tok.range,});}}else if!dropped[i]{out.push(tok.clone());}}settle_indents(&mut out);(out,true)}
/// Moves each `Indent` behind the comment-only lines that now open its block.
///
/// A lexer emits `Indent` at the block's first *logical* line, so comments
/// preceding it come first in the stream. Deleting a docstring can leave
/// comments in front of that first logical line; the verifier re-lexes the
/// output, so the pass has to put the `Indent` where the lexer will. Streams
/// that kept their first statement are untouched: an `Indent` is only ever
/// followed by comments once something before them was removed.
fn settle_indents(tokens:&mut[Tok<'_>]){let mut i=0;while i<tokens.len(){let mut end=i+1;let mut comments=false;if tokens[i].kind==TokenKind::Indent{while end<tokens.len()&&matches!(tokens[end].kind,TokenKind::Comment|TokenKind::NonLogicalNewline){comments|=tokens[end].kind==TokenKind::Comment;end+=1;}}if comments{tokens[i..end].rotate_left(1);}i=end;}}
/// Spans of annotation syntax collected from the AST.
#[derive(Default)]struct AnnotationSpans{
/// Annotation expressions: parameter annotations, the `ann` of an
/// `x: ann = value`, and return annotations alike. Each is widened to a
/// token span by `annotation_span` before anything is cut.
annotations:Vec<TextRange>,
/// Bare `target: ann` statements - replaced by `pass`.
replaced_stmts:Vec<TextRange>,}impl ast::visitor::Visitor<'_>for AnnotationSpans{fn visit_stmt(&mut self,stmt:&ast::Stmt){match stmt{ast::Stmt::AnnAssign(a)=>{if a.value.is_some(){self.annotations.push(a.annotation.range());}else{self.replaced_stmts.push(a.range());}}ast::Stmt::FunctionDef(f)=>{for p in f.parameters.iter(){if let Some(annotation)=p.annotation(){self.annotations.push(annotation.range());}}if let Some(returns)=&f.returns{self.annotations.push(returns.range());}}_=>{}}ast::visitor::walk_stmt(self,stmt);}}
/// Widens an annotation's AST range to everything that has to be cut with it:
/// the `:` / `->` introducing it, and the parentheses wrapping it.
///
/// Ruff's expression ranges exclude enclosing parentheses, so `x: (int) = 1`
/// reports only `int` and would leave `x) = 1` behind. Anchoring the span on
/// the separator token picks up the opening parentheses (everything between
/// the separator and the annotation is `(`), and the closers are then whatever
/// it takes to bring the span back into bracket balance. Balancing rather than
/// counting the leading parentheses matters because the AST range can itself
/// start or end inside a bracket: in `x: (a | (b))` the `| (b)` half opens a
/// pair the range covers, and in `x: ((a) | b)` it closes one it does not.
fn annotation_span(annotation:TextRange,tokens:&[Tok<'_>])->TextRange{let trivia=|kind|matches!(kind,TokenKind::NonLogicalNewline|TokenKind::Comment);let first=tokens.iter().position(|t|t.range.start()>=annotation.start()&&!trivia(t.kind)).expect("annotation has tokens");let mut start=first;while matches!(tokens[start-1].kind,TokenKind::Lpar)||trivia(tokens[start-1].kind){start-=1;}let sep=start-1;let last=tokens.iter().rposition(|t|t.range.end()<=annotation.end()&&!trivia(t.kind)).expect("annotation has tokens");let mut depth=0i32;for tok in&tokens[sep..=last]{depth+=bracket_delta(tok.kind);}let mut end=tokens[last].range.end();for tok in&tokens[last+1..]{if depth==0{break;}depth+=bracket_delta(tok.kind);end=tok.range.end();}TextRange::new(tokens[sep].range.start(),end)}
/// How a token changes bracket nesting depth.
fn bracket_delta(kind:TokenKind)->i32{match kind{TokenKind::Lpar|TokenKind::Lsqb|TokenKind::Lbrace=>1,TokenKind::Rpar|TokenKind::Rsqb|TokenKind::Rbrace=>-1,_=>0,}}
/// Block-structure markers the lexer emits at zero width, positioned *on* a
/// statement boundary rather than between statements: the `Dedent`s closing
/// preceding blocks carry the start offset of the statement that follows them,
/// and a file without a trailing newline gets its final `Newline` (plus the
/// `Dedent`s closing the file) at the end offset of its last statement. Either
/// way they fall within the span of the abutting statement while belonging to
/// the block structure around it, so a whole-statement replacement has to step
/// over them: swallowing a `Dedent` leaves the replacement inside the block
/// that just closed, and swallowing the final `Newline` drops the statement's
/// terminator.
fn is_block_marker(kind:TokenKind)->bool{matches!(kind,TokenKind::Dedent|TokenKind::Newline)}
/// PYO3 - strip type annotations, using AST spans to cut tokens.
pub fn strip_annotations<'a>(tokens:&[Tok<'a>],module:&Module)->(Vec<Tok<'a>>,bool){use ast::visitor::Visitor;let mut spans=AnnotationSpans::default();for stmt in&module.body{spans.visit_stmt(stmt);}let deletes:Vec<TextRange> =spans.annotations.iter().map(|a|annotation_span(*a,tokens)).collect();let modified=!(deletes.is_empty()&&spans.replaced_stmts.is_empty());if!modified{return(tokens.to_vec(),false);}let inside=|t:&Tok<'_>,spans:&[TextRange]|{spans.iter().any(|s|t.range.start()>=s.start()&&t.range.end()<=s.end())};let mut out:Vec<Tok<'a>> =Vec::new();let mut replaced_span:Option<TextRange> =None;for tok in tokens{let replacement=spans.replaced_stmts.iter().find(|s|{!is_block_marker(tok.kind)&&tok.range.start()>=s.start()&&tok.range.end()<=s.end()}).copied();if let Some(span)=replacement{if replaced_span!=Some(span){replaced_span=Some(span);out.push(Tok{kind:TokenKind::Pass,text:"pass",range:tok.range,});}}else if!inside(tok,&deletes){out.push(tok.clone());}}(out,true)}#[cfg(test)]mod tests{use super::*;use crate::parser;fn merge(source:&str)->(String,bool){let parsed=parser::parse(source).unwrap();let(tokens,modified)=merge_imports(&parsed.tokens(source));(crate::emit::render(&tokens,source,&crate::PythonOptions::default()),modified,)}fn strip(source:&str)->(String,bool){let parsed=parser::parse(source).unwrap();let(tokens,modified)=strip_annotations(&parsed.tokens(source),parsed.ast());(crate::emit::render(&tokens,source,&crate::PythonOptions::default()),modified,)}
/// Kinds of the stripped token stream, for order assertions.
fn docstring_kinds(source:&str)->Vec<TokenKind>{let parsed=parser::parse(source).unwrap();let(tokens,_)=strip_docstrings(&parsed.tokens(source),parsed.ast());tokens.iter().map(|t|t.kind).collect()}fn docstrings(source:&str)->(String,bool){let parsed=parser::parse(source).unwrap();let(tokens,modified)=strip_docstrings(&parsed.tokens(source),parsed.ast());(crate::emit::render(&tokens,source,&crate::PythonOptions::default()),modified,)}#[test]fn adjacent_plain_imports_merge(){let(code,modified)=merge("import os\nimport sys\nimport re\n");assert_eq!(code,"import os,sys,re");assert!(modified);}#[test]fn blank_lines_do_not_stop_a_merge(){assert_eq!(merge("import os\n\n\nimport sys\n").0,"import os,sys");}#[test]fn from_imports_merge_only_within_the_same_module(){let(code,_)=merge("from a import b\nfrom a import c as d\nfrom e import f\n");assert_eq!(code,"from a import b,c as d\nfrom e import f");}#[test]fn plain_and_from_imports_do_not_merge_together(){assert_eq!(merge("import os\nfrom re import match\n").0,"import os\nfrom re import match");}#[test]fn relative_import_levels_are_distinct_modules(){let(code,_)=merge("from . import a\nfrom .. import b\n");assert_eq!(code,"from.import a\nfrom..import b");}#[test]fn comments_block_merging(){let(code,modified)=merge("import os\n# group two\nimport sys\n");assert_eq!(code,"import os\n# group two\nimport sys");assert!(!modified);}#[test]fn trailing_comments_block_merging(){let(code,modified)=merge("import os  # core\nimport sys\n");assert_eq!(code,"import os # core\nimport sys");assert!(!modified);}#[test]fn other_statements_block_merging(){assert_eq!(merge("import os\nx = 1\nimport sys\n").0,"import os\nx=1\nimport sys");}#[test]fn parenthesized_star_and_semicolon_imports_are_left_alone(){let(code,modified)=merge("from a import (b)\nfrom a import c\n");assert_eq!(code,"from a import(b)\nfrom a import c");assert!(!modified);assert!(!merge("from a import *\nfrom a import b\n").1);assert!(!merge("import os;import sys\nimport re\n").1);}#[test]fn imports_inside_a_function_merge_at_that_level(){assert_eq!(merge("def f():\n    import os\n    import sys\n    return os\n").0,"def f():\n import os,sys\n return os");}#[test]fn import_as_the_last_line_without_newline_is_untouched(){assert_eq!(merge("import os\nimport sys").0,"import os,sys");}#[test]fn strip_removes_parameter_and_return_annotations(){let(code,modified)=strip("def f(x: int, *args: str, y: float = 1.0, **kw: int) -> int:\n    return x\n");assert_eq!(code,"def f(x,*args,y=1.0,**kw):\n return x");assert!(modified);}#[test]fn strip_rewrites_annotated_assignments(){assert_eq!(strip("x: int = 1\n").0,"x=1");assert_eq!(strip("x: dict[str, int] = {}\n").0,"x={}");}#[test]fn bare_annotations_become_pass(){assert_eq!(strip("class C:\n    x: int\n    y: str\n").0,"class C:\n pass\n pass");}#[test]fn a_bare_annotation_after_a_nested_block_keeps_the_dedents_before_it(){let source="class C:\n    def m(self):\n        return True\n    output_keys: list[str]\n";assert_eq!(strip(source).0,"class C:\n def m(self):\n  return True\n pass");let parsed=parser::parse(source).unwrap();let(tokens,_)=strip_annotations(&parsed.tokens(source),parsed.ast());let kinds:Vec<TokenKind> =tokens.iter().map(|t|t.kind).collect();let pass=kinds.iter().position(|k|*k==TokenKind::Pass).unwrap();assert_eq!(kinds[pass-1],TokenKind::Dedent);}#[test]fn a_bare_annotation_ending_a_file_keeps_its_terminating_newline(){let source="class C:\n    x: int";assert_eq!(strip(source).0,"class C:\n pass");let parsed=parser::parse(source).unwrap();let(tokens,_)=strip_annotations(&parsed.tokens(source),parsed.ast());let kinds:Vec<TokenKind> =tokens.iter().map(|t|t.kind).collect();let pass=kinds.iter().position(|k|*k==TokenKind::Pass).unwrap();assert_eq!(kinds[pass+1..],[TokenKind::Newline,TokenKind::Dedent]);}#[test]fn multiline_return_annotations_are_removed(){let(code,_)=strip("def f(\n    x,\n) -> dict[\n    str,\n    int,\n]:\n    return {}\n");assert_eq!(code,"def f(x,):\n return{}");}#[test]fn parenthesized_annotations_lose_their_parentheses_too(){assert_eq!(strip("x: (int) = 1\n").0,"x=1");assert_eq!(strip("x: ((int)) = 1\n").0,"x=1");assert_eq!(strip("def f(x: (int) = 1) -> (None):\n    return x\n").0,"def f(x=1):\n return x");assert_eq!(strip("def f(\n    x: (\n        int\n    ) = 1,\n):\n    return x\n").0,"def f(x=1,):\n return x");}#[test]fn parentheses_inside_an_annotation_do_not_shorten_the_span(){assert_eq!(strip("x: ((a) | b) = 1\n").0,"x=1");assert_eq!(strip("x: (a | (b)) = 1\n").0,"x=1");assert_eq!(strip("def f(y: (a | (b))) -> ((c) | d):\n    return y\n").0,"def f(y):\n return y");}#[test]fn a_parenthesized_target_keeps_its_own_parentheses(){assert_eq!(strip("(x): int = 1\n").0,"(x)=1");}#[test]fn unannotated_code_is_not_modified(){let(code,modified)=strip("def f(x):\n    return x\n");assert_eq!(code,"def f(x):\n return x");assert!(!modified);}#[test]fn module_docstrings_are_removed(){let(code,modified)=docstrings("\"\"\"Doc.\"\"\"\nx = 1\n");assert_eq!(code,"x=1");assert!(modified);}#[test]fn a_module_of_only_a_docstring_becomes_empty(){assert_eq!(docstrings("\"\"\"Doc.\"\"\"\n").0,"");}#[test]fn function_and_class_docstrings_are_removed(){assert_eq!(docstrings("def f():\n    \"\"\"Doc.\"\"\"\n    return 1\n").0,"def f():\n return 1");assert_eq!(docstrings("async def f():\n    \"\"\"Doc.\"\"\"\n    return 1\n").0,"async def f():\n return 1");assert_eq!(docstrings("class C:\n    \"\"\"Doc.\"\"\"\n    def m(self):\n        \"\"\"Method.\"\"\"\n        return 1\n").0,"class C:\n def m(self):\n  return 1");}#[test]fn docstrings_of_nested_definitions_are_removed(){let(code,_)=docstrings("if flag:\n    def f():\n        \"\"\"Doc.\"\"\"\n        return 1\n");assert_eq!(code,"if flag:\n def f():\n  return 1");}#[test]fn a_sole_docstring_body_becomes_pass(){assert_eq!(docstrings("def f():\n    \"\"\"Doc.\"\"\"\n").0,"def f():\n pass");assert_eq!(docstrings("class C:\n    \"\"\"Doc.\"\"\"\n").0,"class C:\n pass");assert_eq!(docstrings("def f(): \"\"\"Doc.\"\"\"\n").0,"def f():pass");}#[test]fn a_comment_after_a_sole_docstring_survives(){assert_eq!(docstrings("def f():\n    \"\"\"Doc.\"\"\"\n    # note\n").0,"def f():\n pass\n# note");}#[test]fn a_trailing_comment_on_the_docstring_line_survives(){assert_eq!(docstrings("\"\"\"Doc.\"\"\"  # note\nx = 1\n").0,"# note\nx=1");}#[test]fn comments_starting_a_body_move_ahead_of_the_block_indent(){for(source,expected)in[("def f():\n    \"\"\"Doc.\"\"\"  # note\n    return 1\n","def f():\n # note\n return 1",),("class C:\n    \"\"\"Doc.\"\"\"\n\n    # note\n    x = 1\n","class C:\n # note\n x=1",),]{assert_eq!(docstrings(source).0,expected);let kinds=docstring_kinds(source);let indent=kinds.iter().position(|k|*k==TokenKind::Indent).unwrap();let comment=kinds.iter().position(|k|*k==TokenKind::Comment).unwrap();assert!(comment<indent,"comment must precede Indent in {source:?}");}let kinds=docstring_kinds("class C:\n    \"\"\"Doc.\"\"\"\n    x = 1\n");let indent=kinds.iter().position(|k|*k==TokenKind::Indent).unwrap();assert_eq!(kinds[indent+1],TokenKind::Name);}#[test]fn a_semicolon_terminated_docstring_is_removed_with_its_separator(){assert_eq!(docstrings("\"\"\"Doc.\"\"\";x = 1\n").0,"x=1");}#[test]fn implicitly_concatenated_and_parenthesized_docstrings_are_removed(){assert_eq!(docstrings("def f():\n    \"a\" \"b\"\n    return 1\n").0,"def f():\n return 1");assert_eq!(docstrings("def f():\n    (\"Doc.\")\n    return 1\n").0,"def f():\n return 1");}#[test]fn fstrings_and_byte_strings_are_not_docstrings(){let(code,modified)=docstrings("def f():\n    f\"{x}\"\n    return 1\n");assert_eq!(code,"def f():\n f\"{x}\"\n return 1");assert!(!modified);let(code,modified)=docstrings("def f():\n    b\"doc\"\n    return 1\n");assert_eq!(code,"def f():\n b\"doc\"\n return 1");assert!(!modified);}#[test]fn string_statements_that_are_not_first_are_kept(){let(code,modified)=docstrings("def f():\n    x = 1\n    \"note\"\n");assert_eq!(code,"def f():\n x=1\n \"note\"");assert!(!modified);let(code,modified)=docstrings("if flag:\n    \"note\"\n");assert_eq!(code,"if flag:\n \"note\"");assert!(!modified);}#[test]fn sources_without_docstrings_are_not_modified(){let(code,modified)=docstrings("def f():\n    return 1\n");assert_eq!(code,"def f():\n return 1");assert!(!modified);}#[test]fn nested_functions_and_methods_are_stripped_too(){let(code,_)=strip("class C:\n    def m(self, x: int) -> None:\n        def g(y: str) -> str:\n            return y\n        return g\n");assert_eq!(code,"class C:\n def m(self,x):\n  def g(y):\n   return y\n  return g");}}